fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Ensure the inputs are compatible
    assert_eq!(
        a.len(),
        mask.len(),
        "Input array and mask must have the same length"
    );
    assert!(
        !values.is_empty(),
        "Replacement values array must be non-empty"
    );

    let n = a.len();
    let m = values.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        if mask[i] {
            // pick replacement value in a cyclic fashion
            result.push(values[i % m]);
        } else {
            // keep the original value
            result.push(a[i]);
        }
    }

    result
}

