    #[test]
    fn test_putmask_basic() {
        let a = vec![1.0, 2.0, 3.0, 4.0];
        let mask = vec![false, true, false, true];
        let values = vec![10.0, 20.0];
        let res = putmask(a, mask, values);
        // At positions 1 and 3 we use values[1 % 2] = values[1] = 20.0,
        // and values[3 % 2] = values[1] = 20.0
        assert_eq!(res, vec![1.0, 20.0, 3.0, 20.0]);
    }

    #[test]
    fn test_putmask_wraparound() {
        let a = vec![0.0; 5];
        let mask = vec![true; 5];
        let values = vec![7.0, 8.0, 9.0];
        let res = putmask(a, mask, values);
        // Values should cycle: 7,8,9,7,8
        assert_eq!(res, vec![7.0, 8.0, 9.0, 7.0, 8.0]);
    }

    #[test]
